#pragma once#include <stdlib.h>#ifdef HBRIDGE2SYSPARAM_EXPORTS#define HBRIDGE2SYSPARAM_API Q_DECL_DLLEXPORT     #else#define HBRIDGE2SYSPARAM_API Q_DECL_DLLIMPORT     #endifstruct SQbParam{  char ParamName[64];  void *pAddr;  int Size;  char Type;};class KQbBridge2SysParam{  SQbParam *m_Params;  int m_Used, m_countParams;public:  KQbBridge2SysParam( SQbParam *pParams, int countParams )    : m_Used(0)    , m_countParams(countParams)    , m_Params(pParams)  {  }  int Count()  {    return m_Used;  }  SQbParam& Add( double &val, LPCSTR pName )  {    SQbParam &Y = push( pName, val );    Y.Type = 'D';    return Y;  }  SQbParam& Add( int &val, LPCSTR pName )  {    SQbParam &Y = push( pName, val );    Y.Type = 'I';    return Y;  }  SQbParam& Add( BYTE &val, LPCSTR pName )  {    SQbParam &Y = push( pName, val );    Y.Type = 'W';    return Y;  }  SQbParam& Add( short &val, LPCSTR pName )  {    SQbParam &Y = push( pName, val );    Y.Type = 'H';    return Y;  }  SQbParam& Add( float &val, LPCSTR pName )  {    SQbParam &Y = push( pName, val );    Y.Type = 'F';    return Y;  }  SQbParam& Add( bool &val, LPCSTR pName )  {    SQbParam &Y = push( pName, val );    Y.Type = 'B';    return Y;  }  template<size_t _S>  SQbParam& Add( char (&val)[_S], LPCSTR pName )  {    SQbParam &Y = push( pName, val );    Y.Type = 'S';    Y.Size = _S;    return Y;  }protected:  template<typename T>  SQbParam& push( LPCSTR pName, T &val )  {    if( m_Used>=m_countParams )      throw "дальнейшая работа невозможна";    SQbParam& H = m_Params[m_Used];    ++m_Used;    strcpy_s( H.ParamName, pName );    H.pAddr = &val;    H.Size = sizeof(val);    return H;  }};